// Builds the documentation's search index.
//
// The search box in the sidebar looks across page titles *and* the headings
// inside them, which means it has to know the headings of pages the reader has
// not opened. Loading 72 pages to find out is not an option, so the headings are
// read out of the sources at build time and written to one small module.
//
// Run by `npm run build` in this directory (and so by `npm run build` at the
// repository root, which builds the documentation first). The generated file is
// checked in, so a plain `tsc -b` in a fresh clone still typechecks.
//
//   node scripts/gen-search-index.mjs           write src/searchIndex.generated.ts
//   node scripts/gen-search-index.mjs --check   fail if it is out of date
//
// The `--check` form is what catches a stale index in a build rather than
// letting one ship.

import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const SRC = join(here, '..', 'src')
const OUT = join(SRC, 'searchIndex.generated.ts')

/** `Section title` -> `section-title`, the id `DocPage` gives that heading. */
export function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .trim()
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
}

// Which page component renders which route. Read out of the route table rather
// than guessed, so a page that moves does not silently drop out of search.
function routeToComponent() {
  const app = readFileSync(join(SRC, 'App.tsx'), 'utf8')
  const imports = new Map()
  for (const m of app.matchAll(/import\s+(\w+)\s+from\s+'\.\/pages\/(\w+)'/g)) {
    imports.set(m[1], `${m[2]}.tsx`)
  }
  const routes = new Map()
  for (const m of app.matchAll(/\[\s*'([^']+)'\s*,\s*<(\w+)\s*\/>\s*\]/g)) {
    const file = imports.get(m[2])
    if (file) routes.set(m[1], file)
  }
  return routes
}

// Headings as they are written in a page: `<h2>Text</h2>` or `<h2 id="x">Text`.
// Anything with an expression in it is skipped rather than guessed at — a
// heading whose text is computed is not something a static read can resolve.
// A heading is written as JSX, so it can carry HTML entities. The index holds
// what a reader sees, not what the source says.
const ENTITIES = {
  '&amp;': '&', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&#39;': "'",
  '&apos;': "'", '&nbsp;': ' ', '&mdash;': '\u2014', '&ndash;': '\u2013',
}

function decode(text) {
  return text.replace(/&(?:amp|lt|gt|quot|#39|apos|nbsp|mdash|ndash);/g, (e) => ENTITIES[e] ?? e)
}

function headingsOf(source) {
  const out = []
  for (const m of source.matchAll(/<(h2|h3)\b([^>]*)>([^<{]+)</g)) {
    const text = decode(m[3].replace(/\s+/g, ' ').trim())
    if (!text) continue
    const id = /id="([^"]+)"/.exec(m[2])
    out.push({ level: m[1] === 'h2' ? 2 : 3, text, id: id ? id[1] : slugify(text) })
  }
  return out
}

function build() {
  const routes = routeToComponent()
  const files = new Set(readdirSync(join(SRC, 'pages')).filter((n) => n.endsWith('.tsx')))
  const entries = []
  for (const [route, file] of [...routes].sort((a, b) => a[0].localeCompare(b[0]))) {
    if (!files.has(file)) continue
    const headings = headingsOf(readFileSync(join(SRC, 'pages', file), 'utf8'))
    if (headings.length) entries.push([route, headings])
  }

  const body = entries
    .map(
      ([route, headings]) =>
        `  '${route}': [\n` +
        headings
          .map((h) => `    { level: ${h.level}, text: ${JSON.stringify(h.text)}, id: '${h.id}' },`)
          .join('\n') +
        '\n  ],',
    )
    .join('\n')

  const total = entries.reduce((n, [, h]) => n + h.length, 0)
  return `// GENERATED by scripts/gen-search-index.mjs — do not edit by hand.
//
// The headings of every documentation page, so the sidebar's search can find a
// section without the page it lives on having been opened. Regenerated by
// \`npm run build\`; \`node scripts/gen-search-index.mjs --check\` fails when it is
// out of date.
//
// ${entries.length} pages, ${total} headings.

export interface IndexedHeading {
  level: 2 | 3
  text: string
  id: string
}

export const HEADINGS: Record<string, IndexedHeading[]> = {
${body}
}
`
}

const next = build()
if (process.argv.includes('--check')) {
  let current = ''
  try {
    current = readFileSync(OUT, 'utf8')
  } catch {
    /* not written yet */
  }
  if (current !== next) {
    console.error('src/searchIndex.generated.ts is out of date. Run: node scripts/gen-search-index.mjs')
    process.exit(1)
  }
  console.log('src/searchIndex.generated.ts is up to date.')
} else {
  writeFileSync(OUT, next)
  const pages = (next.match(/^  '/gm) || []).length
  const headings = (next.match(/^    \{ level:/gm) || []).length
  console.log(`src/searchIndex.generated.ts: ${pages} pages, ${headings} headings.`)
}
